class InventoryManager:
    def __init__(self):
        self.items = []
        self.logger = logging.getLogger("InventoryManager")

    def add_item(self, item_name, quantity=1):
        """Add an item to the inventory and log its call."""
        self.logger.info(f"Added item '{item_name}' with quantity {quantity}")
        self.items.append({"name": item_name, "quantity": quantity})

    def remove_item(self, item_id):
        """Remove an item by ID from the inventory and log its call."""
        try:
            index = self._find_index_by_key(item_id)
            if 0 <= index < len(self.items):
                self.logger.info(f"Removed item '{self.items[index]['name']}'")
                del self.items[index]
            else:
                raise ValueError("Item not found in inventory")
        except KeyError as e:
            self.logger.error(f"Error finding item by ID {e}")

    def get_count(self):
        """Return the total number of items and log its call."""
        return len(self.items)

    def _find_index_by_key(self, key):
        """Find the index of an item by name using a dictionary lookup for fast access."""
        for i, item in enumerate(self.items):
            if item["name"] == key:
                return i
        raise ValueError(f"Item '{key}' not found")

    def log_all_calls(self):
        """Log all methods called during execution."""
        print("\n=== InventoryManager Methods Called ===\n")
        for method_name in dir(self):
            if self.__dict__.hasattr(method_name, "__call__"):
                func = getattr(self, method_name)
                call_args = getattr(func, "_call_args", None)
                if not call_args:
                    continue
                try:
                    func(*call_args)
                except Exception as e:
                    self.logger.error(f"Error calling {method_name}: {e}")

    def __enter__(self):
        """Context manager entry."""
        return self

    def __exit__(self, *args):
        """Context manager exit."""
        pass  # Exit without raising exceptions

