class InventoryManager:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.items = {}  # Stores item name (key) and quantity (default 0)

    def add_item(self, item_name, quantity=1):
        """Log the call and read or update the items dictionary."""
        try:
            key = f"{self.logger.name}.{item_name}"

            if not isinstance(item_name, str):
                raise TypeError("Item name must be a string")

            if self.items.get(key) == 0:
                # First time reading this item
                self.items[key] = quantity
            else:
                # Updating existing entry
                old_quantity = self.items[key]
                new_quantity = old_quantity + quantity

                # Log the update
                self.logger.info(f"Added or updated quantity for {item_name}: from {old_quantity} to {new_quantity}")

        except Exception as e:
            self.logger.error(f"Error reading/update item '{self.logger.name}.{item_name}': {str(e)}")

    def remove_item(self, item_name):
        """Log the call and read or update the items dictionary."""
        try:
            key = f"{self.logger.name}.{item_name}"

            if self.items.get(key) == 0:
                # Item not found
                raise ValueError(f"Item '{self.logger.name}.{item_name}' does not exist")

            # Reading/Updating logic identical to add_item
            old_quantity = self.items[key]
            new_quantity = old_quantity + quantity if quantity > 0 else (old_quantity - quantity)

            self.items[key] = new_quantity

        except Exception as e:
            self.logger.error(f"Error reading/update item '{self.logger.name}.{item_name}': {str(e)}")

    def get_count(self, item_name):
        """Log the call and read or update the items dictionary."""
        try:
            key = f"{self.logger.name}.{item_name}"

            if self.items.get(key) == 0:
                raise ValueError(f"Item '{self.logger.name}.{item_name}' does not exist")

            return self.items[key]

        except Exception as e:
            self.logger.error(f"Error reading item '{self.logger.name}.{item_name}': {str(e)}")
