from typing import List, Any

class InventoryManager:
    def __init__(self):
        # Initialize default items if empty
        if not hasattr(self, 'items'):
            self.items = []

    def add_item(self, item: Any) -> None:
        """Add an item to the inventory."""
        if isinstance(item, str):
            item_str = item.strip()
            if item_str and len(item_str) > 0:
                self._add_item_from_string(item_str)
        else:
            # For types not specified in string format (e.g., numbers), use a placeholder or default
            self._add_item_by_default()

    def _add_item_by_default(self, item: Any) -> None:
        """Add an item by default if it's not already in the list."""
        if item is None:
            return  # No action needed for None
        if isinstance(item, str):
            self._add_item_from_string(str(item))
        else:
            # If no string was provided and it's a type like int/float/etc., use the default logic below or raise an error.
            pass

    def _add_item_from_string(self, s: str) -> None:
        """Add items from a string representation."""
        try:
            if isinstance(s, list):
                for item in s:
                    self._add_item_by_default(item)
            else:
                # For non-list strings, assume they're single items or use the default.
                pass

    def remove_item(self, index: int | None = None) -> None:
        """Remove an item by index or remove all."""
        if index is None:
            self._remove_all()
        else:
            for i in range(len(self.items)):
                if i == index:
                    del self.items[i]

    def _remove_all(self) -> None:
        """Remove all items from the inventory."""
        self.items = []

    def get_count(self) -> int:
        """Get the total count of items in the inventory."""
        return len(self.items)
