class InventoryManager:
    def __init__(self):
        # Initialize items list if not already present (read/write)
        if not hasattr(self, 'items'):
            self.items = []

        # Set up logger for logging calls to self.logger.info
        self.logger = self.__dict__.get('logger', None)

    def add_item(self):
        """Add a new item and log the call"""
        self._add_to_list()
        if self.logger:
            self.logger.info("Item added successfully")

    def _add_to_list(self):
        """Add the given item to the items list (read/write)"""
        try:
            item = input(f"Enter a new item name ({self.logger}): ").strip().lower()
            if not item:
                return

            self._update_item(item)

            # Log successful addition
            print("Item added successfully")

    def remove_item(self):
        """Remove an existing item and log the call"""
        try:
            while True:
                item = input(f"Enter a name to remove ({self.logger}): ").strip().lower()

                if not item:
                    break

                # Update state (read/write)
                self._remove_from_list(item)

                print("Item removed successfully")

        except KeyError as e:
            print("Error: Item not found. Try again.")
            raise

    def _update_item(self, item):
        """Update the item in the list"""
        try:
            index = self._index_in_list(item)
            if 0 <= index < len(self.items):
                del self.items[index]

                # Log successful update
                print(f"Item '{item}' removed from inventory")

    def _remove_from_list(self, item):
        """Remove the given item from the list"""
        try:
            idx = self._index_in_list(item.replace(' ', ''))  # Replace spaces to get unique index for removal
            if 0 <= idx < len(self.items):
                del self.items[idx]

                print("Item removed successfully")

    def _index_in_list(self, item):
        """Helper method to find the index of a string in the list"""
        return self._find_index_by_item(item)

    def _find_index_by_item(self, item):
        """Find the index of an item containing a specific substring"""
        for i, item_val in enumerate(self.items):
            if str(item_val).lower().startswith(str(item)):
                return i

        raise ValueError(f"Item '{item}' not found")

    def get_count(self):
        """Get and log the current count of items (read/write)"""
        print("Inventory count: " + str(len(self.items)))

