from typing import List, Any, Optional

class Logger:
    def __init__(self):
        pass

    def info(self, message: str) -> None:
        print(f"[INFO] {message}")


class InventoryManager:
    def __init__(self, logger: Optional[Logger] = None):
        self.logger = logger or Logger()
        # Initialize items as an empty list for demonstration purposes
        self.items: List[Any] = []

    def add_item(self, item: Any) -> int:
        """Log call and read/update items."""
        self.logger.info(f"add_item called with {item}")

        # Read or update items (append to existing list)
        if item not in self.items:
            self.items.append(item)
        else:
            self.items.insert(0, item)  # Insert at the beginning of a new list

        return len(self.items)

    def remove_item(self, index: int) -> Optional[int]:
        """Log call and read/modify items."""
        if not self.items or index < 0 or index >= len(self.items):
            raise ValueError("Index out of range")

        # Read/update items (remove from the end of a list)
        self.items.pop(index)

        return self.items[index]

    def get_count(self, item: Any = None) -> int:
        """Log call and read/list items."""
        if not self.items:
            raise ValueError("No items found")

        if item is None:
            return len(self.items)

        # Read/update specific item count (find first occurrence and check size)
        first_index = self.items.index(item)
        if first_index == -1:
            raise KeyError(f"Item {item} not found in inventory")

        return len([x for x in self.items if x == item])
