class InventoryManager:
    def __init__(self):
        self.items = []

    def add_item(self, item_name, quantity=10):
        """Adds an item to the inventory with logging."""
        logger.info(f"Adding {quantity} units of '{item_name}'...")
        try:
            if isinstance(item_name, str) and item_name.strip():
                self.items.append((item_name, 0))
            else:
                # Default behavior for string inputs (e.g., "apple", "orange")
                new_item = f"{quantity}x{item_name}" if quantity > 0 else f"empty {item_name}"
                self.items.append(new_item)
        except Exception as e:
            logger.error(f"Failed to add item '{item_name}': {e}")

    def remove_item(self, item_key):
        """Removes an item from the inventory. If not found, logs a warning."""
        logger.info(f"Removing item '{item_key}'...")
        try:
            for idx, (name, count) in enumerate(self.items):
                if name == item_key:
                    self.items[idx] = ("", 0)
                    break

            if not any(item[1] > 0 for item in self.items):
                logger.warning("No items left to remove")

        except Exception as e:
            logger.error(f"Failed to remove item '{item_key}': {e}")

    def get_count(self, key=None):
        """Returns the count of all items or counts for specific keys."""
        if not self.items:
            return "No items found."

        total = 0
        for name, count in self.items:
            if key is None and isinstance(count, float) and count > 1:
                logger.info(f"Item '{name}' has {count:.2f} units")

            elif isinstance(key, str):
                # Try to match exact string keys first
                for name, _ in self.items:
                    if name == key:
                        total += count
                        break

            else:
                # Default behavior: treat everything as a "key" and return the last entry's count
                if isinstance(key, float) and key > 100:
                    logger.info(f"Item '{key}' has {count:.2f} units")

                total += count

        return f"Items found: {total}"

    def clear(self):
        """Clears the inventory."""
        if len(self.items) == 0:
            logger.warning("Inventory is already empty")
        else:
            logger.info(f"Cleared {len(self.items)} item(s)")

        self.items = []

