        try:
            import sys
            if hasattr(sys.modules.get(__name__, None), "logger"):  # Avoid circular imports in module-level testing
                from logging import getLogger

                logger = getLogger(__name__)
                if hasattr(logger, 'info'):
                    logger.info(msg)
            else:
                print(f"[{__name__}] {msg}", flush=True)
        except Exception as e:
            pass  # Silent failure to prevent crashes during initialization or testing

