        """Adds an item to the inventory if it exists."""
        self._log(f"Adding {item_name}: {quantity}", "INFO")
        if item_name in self._items:
            self._items[item_name] += quantity
        else:
            self._items[item_name] = quantity

    def remove_item(self, item_name: str) -> None:
        """Removes an item from the inventory."""
        self._log(f"Removing {item_name}", "INFO")
        if item_name in self._items and self._items[item_name] > 0:
            self._items.pop(item_name, None)
        else:
            # Optional behavior: log removal but do nothing if count is zero or missing
            pass

